# --- Provider definitions (CLI-first, non-interactive) ---

anthropic_opus41:
  cmd: ["claude", "messages", "create"]
  model: "claude-4.1-opus"
  flags: ["--dangerously-skip-permissions", "--quiet"]
  stdin_mode: "messages_json"              # подаём messages через stdin
  output_parser: "json"                    # ожидаем JSON из tools
  tool_schema_ref_from_role: true          # брать JSON-schema из role.json_schema_ref как tool
  env_required: ["ANTHROPIC_API_KEY"]

anthropic_sonnet4:
  cmd: ["claude", "messages", "create"]
  model: "claude-4.1-sonnet"
  flags: ["--dangerously-skip-permissions", "--quiet"]
  stdin_mode: "messages_json"
  output_parser: "json"
  tool_schema_ref_from_role: true
  env_required: ["ANTHROPIC_API_KEY"]

openai_gpt5:
  cmd: ["openai", "responses.create"]
  model: "gpt-5"
  flags: ["--quiet"]
  stdin_mode: "messages_json"
  output_parser: "json"
  response_format: "json_schema"           # строгий JSON по схеме
  json_schema_ref_from_role: true
  env_required: ["OPENAI_API_KEY"]

openai_gpt5_mini:
  cmd: ["openai", "responses.create"]
  model: "gpt-5-mini"
  flags: ["--quiet"]
  stdin_mode: "messages_json"
  output_parser: "json"
  response_format: "json_object"           # упрощённый строгий JSON
  env_required: ["OPENAI_API_KEY"]

gemini_25_pro:
  cmd: ["gemini", "generate"]
  model: "gemini-2.5-pro"
  flags: ["-y", "--quiet"]
