  flags: [\"-m\", \"gemini-2.5-pro\"]\n    output_parser: \"text\"\n    modes:\n      reasoning: { model: \"pro\" }\n      fast: { model: \"flash\" }\n    auth:\n      refresh_secret_key: \"GEMINI_REFRESH_TOKEN\"\n      token_endpoint: \"https://oauth2.googleapis.com/token\"\n      client_id: \"<SECRET:GEMINI_OAUTH_CLIENT_ID>\"\n      client_secret: \"<SECRET:GEMINI_OAUTH_CLIENT_SECRET>\"\n      scope: \"https://www.googleapis.com/auth/cloud-platform\"\n      access_env: \"GOOGLE_OAUTH_ACCESS_TOKEN\"      # передаем токен в окружение\n      local_config_file: \"/home/feature/.gemini/oauth_creds.json\"  # атомарно обновляем\n\n  codex:\n    binary_path: \"/opt/feature-factory/bin/codex\"\n    probe: [\"--version\"]\n    stdin: \"messages_json\"\n    env: {}\n    flags:\n      base: [\"exec\", \"--dangerously-bypass-approvals-and-sandbox\", \"--skip-git-repo-check\", \"-m\", \"gpt-5\", \"--output-last-message\", \"${OUTFILE}\"]\n    models:\n      default:\n        id: \"gpt-5\"\n    output_parser: \"textfile\"\n    outfile_template: \"/tmp/ff_codex_last_${UUID}.txt\"\n    modes:\n      reasoning: { model: \"default\" }\n      fast: { model: \"default\" }\n\n  qwen:\n    binary_path: \"/usr/local/bin/qwen\"\n    probe: [\"--version\"]\n    stdin: \"prompt\"\n    env:\n      HOME: \"/home/feature\"\n      QWEN_API_KEY: \"<SECRET:QWEN_API_KEY>\"\n    flags:\n      base: [\"run\", \"-y\", \"--no-color\", \"--quiet\"]\n    models:\n      default:\n        id: \"qwen-code-latest\"\n    output_parser: \"text\"\n    modes:\n      reasoning: { model: \"default\" }\n      fast: { model: \"default\" }\n    auth:\n      refresh_secret_key: \"QWEN_REFRESH_TOKEN\"     # опционально; если недоступно — будет пропущено\n\n# Provider aliases map existing routing names to declarative providers/variants\naliases:\n  anthropic_opus41: { provider: \"claude\", model: \"sonnet4\" }\n  claude_chat:      { provider: \"claude\", model: \"sonnet4\" }\n  gemini_25_pro:    { provider: \"gemini\",